    12→/// 소스 코드를 LLVM IR 텍스트로 컴파일하는 헬퍼 함수
    13→fn compileToLLVMIR(source: []const u8, allocator: std.mem.Allocator) ![]const u8 {
    14→    var tokenizer = try Tokenizer.init(source, allocator);
    15→    defer tokenizer.deinit();
    16→
    17→    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    18→    defer tokens.deinit();
    19→
    20→    while (try tokenizer.nextToken()) |token| {
    21→        try tokens.append(token);
    22→    }
    23→
    24→    var parser = try Parser.init(tokens.items, source, allocator);
    25→    defer parser.deinit();
    26→    const ast = try parser.parseProgram();
    27→
    28→    var astgen = try AstGen.init(allocator, source);
    29→    defer astgen.deinit();
    30→    try astgen.genProgram(&ast);
    31→
    32→    var sema = try Sema.init(allocator, &astgen.zir);
    33→    defer sema.deinit();
    34→    try sema.analyzeProgram();
    35→
    36→    var llvm_ir = try LLVMIRGen.init(allocator, &sema.air);
    37→    defer llvm_ir.deinit();
    38→    return try llvm_ir.generate();
    39→}
