    49→
    50→    const source = "const x = 42;";
    51→    const ir_text = try compileToLLVMIR(source, allocator);
    52→    defer allocator.free(ir_text);
    53→
    54→    const test_file = "/tmp/zig_test_ir_1.ll";
    55→    defer {
    56→        std.fs.cwd().deleteFile(test_file) catch {};
    57→    }
    58→
    59→    try Linker.writeIRToFile(ir_text, test_file);
    60→    try std.testing.expect(Linker.fileExists(test_file));
    61→}
